<?php
declare(strict_types=1);
require_once __DIR__.'/../../includes/auth.php';require_once __DIR__.'/../../config/db.php';require_once __DIR__.'/../../includes/audit.php';
if(!isSuperUser()){http_response_code(403);exit('Access denied.');}
if($_SERVER['REQUEST_METHOD']!=='POST'){header('Location:index.php');exit;}verify_csrf();
$modules=['products','categories','brands','price_lists','customers','suppliers','purchases','sales','customer_payments','supplier_payments','deliveries','stock_movements','expenses','finance','billing','reports','analytics','supply_chain','mpesa','staff','sales_returns','cash_management','stocktaking','audit_logs','etims','launch_controls','hr','chart_of_accounts','journals','general_ledger','trial_balance'];
try{$action=(string)($_POST['action']??'');
if($action==='create'){$name=trim((string)($_POST['role_name']??''));$desc=trim((string)($_POST['description']??''));if($name==='')throw new RuntimeException('Enter a role name.');$base=substr(strtoupper(trim(preg_replace('/[^a-zA-Z0-9]+/','_',$name),'_')),0,45);if($base==='')throw new RuntimeException('Role name must contain letters or numbers.');$code=$base;$n=2;$q=$conn->prepare("SELECT COUNT(*) FROM roles WHERE role_code=?");while(true){$q->execute([$code]);if(!(int)$q->fetchColumn())break;$code=substr($base,0,45-strlen((string)$n)).'_'.$n++;}$q=$conn->prepare("INSERT INTO roles(role_code,role_name,description,is_system,status) VALUES(?,?,?,0,'Active')");$q->execute([$code,$name,$desc?:null]);$id=(int)$conn->lastInsertId();recordAuditEvent($conn,'Create','roles','Created role '.$name,'role',$id,null,['role_code'=>$code]);$_SESSION['role_flash']='Role created. Configure its permissions.';header('Location:index.php?id='.$id);exit;}
if($action==='save_permissions'){$id=(int)($_POST['role_id']??0);$q=$conn->prepare("SELECT id FROM roles WHERE id=?");$q->execute([$id]);if(!$q->fetch())throw new RuntimeException('Role not found.');$submitted=$_POST['permissions']??[];if(!is_array($submitted))$submitted=[];$conn->beginTransaction();$conn->prepare("DELETE FROM role_permissions WHERE role_id=?")->execute([$id]);$ins=$conn->prepare("INSERT INTO role_permissions(role_id,module_key,can_view,can_create,can_edit,can_delete) VALUES(?,?,?,?,?,?)");foreach($modules as $m){$p=$submitted[$m]??[];if(!is_array($p))$p=[];$v=isset($p['view'])?1:0;$c=isset($p['create'])&&$v?1:0;$e=isset($p['edit'])&&$v?1:0;$d=isset($p['delete'])&&$v?1:0;if($v)$ins->execute([$id,$m,$v,$c,$e,$d]);}recordAuditEvent($conn,'Update Permissions','roles','Updated permissions for role ID '.$id,'role',$id);$conn->commit();$_SESSION['role_flash']='Role permissions saved successfully.';header('Location:index.php?id='.$id);exit;}
throw new RuntimeException('Invalid role action.');
}catch(Throwable $e){if($conn->inTransaction())$conn->rollBack();$_SESSION['role_flash']='Role update failed: '.$e->getMessage();header('Location:index.php');exit;}
?>